with.script:
const newly = (process.env.NEWLY || '').trim();
const collabVacuous = process.env.COLLAB_VACUOUS === 'true';
const lines = [
  '**Behavioral/collab watchdog tripped on a push to `main`.**',
  '',
  `Run: ${context.serverUrl}/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId}`,
  `Commit: ${context.sha}`,
  '',
];
if (newly) {
  lines.push(
    '### Reproduced behavioral regression',
    `NEWLY-failing modules (green at the last-green baseline, now failing — and failed AGAIN on the targeted re-run): **${newly.split(' ').filter(Boolean).join(', ')}**`,
    '',
    `All currently-failing behavioral modules: ${process.env.FAILED_MODULES || '(none)'}`,
    '',
  );
}
if (collabVacuous) {
  lines.push(
    '### @collab ran VACUOUS',
    `The committed @collab attestation for the current collab content hash was NOT produced with a real DATABASE (${process.env.COLLAB_REASON}). A green @collab lane here proves nothing about multi-user behaviour — re-attest with a real Postgres (\`flox activate -- task collab:attest\`).`,
    '',
  );
}
lines.push(
  'This issue emails repo watchers (incl. tmayshark@gmail.com) via the same alert path as `live-smoke-alert.yml` (#1105). Root-cause immediately — a red push on `main` is a P0.',
);
const title = newly
  ? `[P0] main red: behavioral regression — ${newly.split(' ').filter(Boolean).slice(0, 4).join(', ')}`
  : '[P0] main red: @collab attestation ran VACUOUS';
await github.rest.issues.create({
  owner: context.repo.owner,
  repo: context.repo.repo,
  title,
  body: lines.join('\n'),
  labels: ['p0', 'behavioral-regression', 'main-red', 'observability', 'alert'],
});

const fs = require('fs');
const marker = '<!-- vrt-failure-gallery -->';
const url = process.env.GALLERY_URL;
const count = process.env.COUNT;
const headRef = process.env.HEAD_REF;
let summary = '';
try {
  const j = JSON.parse(fs.readFileSync('/tmp/vrt-failure.json', 'utf8'));
  const bits = [];
  if (j.modified) bits.push(`${j.modified} changed`);
  if (j.added) bits.push(`${j.added} new`);
  summary = bits.length ? ` (${bits.join(', ')})` : '';
} catch {}
const body = [
  marker,
  `### ⚠️ VRT changed — review before merge`,
  ``,
  `The informational \`vrt\` lane rendered **${count}** baseline${count === '1' ? '' : 's'} differently${summary}. Review each as OLD / NEW / DIFF, with a draggable slider + onion-skin:`,
  ``,
  `**[▶ View the VRT diff gallery →](${url})**`,
  ``,
  `If the change is INTENTIONAL, accept the new baselines (regenerated on`,
  `linux + darwin by CI, committed back to this branch) by running EITHER:`,
  ``,
  '```',
  `# from a local checkout of this branch:`,
  `flox activate -- task vrt:commit`,
  ``,
  `# or trigger the CI job directly from anywhere:`,
  `gh workflow run vrt-update.yml -f ref=${headRef}`,
  '```',
  ``,
  `<sub>Built from this run's Playwright results by \`scripts/vrt-changeset-gallery.mjs --from-results\`. Re-renders on every push. The full \`vrt\` lane is informational (does not block merge); \`vrt-strict\` remains the required gate.</sub>`,
].join('\n');
const { owner, repo } = context.repo;
const issue_number = context.payload.pull_request.number;
const comments = await github.paginate(github.rest.issues.listComments, {
  owner, repo, issue_number, per_page: 100,
});
const existing = comments.find((c) => c.body && c.body.includes(marker));
if (existing) {
  await github.rest.issues.updateComment({ owner, repo, comment_id: existing.id, body });
  core.info(`Updated existing comment ${existing.id}`);
} else {
  await github.rest.issues.createComment({ owner, repo, issue_number, body });
  core.info('Created new failure-gallery comment');
}

