with.script:
const headRef = context.payload.pull_request?.head?.ref;
if (headRef === "changeset-release/master") {
  core.info("Skipping changeset guard for changeset-release/master");
  return;
}

const files = await github.paginate(github.rest.pulls.listFiles, {
  owner: context.repo.owner,
  repo: context.repo.repo,
  pull_number: context.payload.pull_request.number,
  per_page: 100,
});

const changedFiles = files.map((file) => file.filename);
if (changedFiles.length === 0) {
  core.info("No changed files detected");
  return;
}

const releaseImpactPrefixes = [
  "packages/core/",
  "apps/web/",
  "apps/desktop/",
  "examples/wasm-standard/",
  "examples/web-simple/",
];

const hasChangeset = changedFiles.some(
  (name) => name.startsWith(".changeset/") && name.endsWith(".md"),
);
const hasReleaseImpact = changedFiles.some((name) =>
  releaseImpactPrefixes.some((prefix) => name.startsWith(prefix)),
);

core.info(`Changed files: ${changedFiles.length}`);
core.info(`hasChangeset=${hasChangeset} hasReleaseImpact=${hasReleaseImpact}`);

if (hasReleaseImpact && !hasChangeset) {
  core.setFailed("Release-impacting files changed without a .changeset/*.md entry. Run: pnpm changeset");
}

const fs = require("fs");
const path = require("path");
const scriptPath = path.join(process.env.GITHUB_WORKSPACE, ".github/scripts/post-compression-comment.js");
const body = fs.readFileSync(scriptPath, "utf8");
const run = new Function("github", "context", "core", "return (async function () {\n" + body + "\n})();");
await run(github, context, core);

const fs = require("fs");
const path = require("path");
const scriptPath = path.join(process.env.GITHUB_WORKSPACE, ".github/scripts/post-preview-comment.js");
const body = fs.readFileSync(scriptPath, "utf8");
const run = new Function(
    "github",
    "context",
    "core",
    "return (async function () {\n" + body + "\n})();",
);
await run(github, context, core);

