    for (const change of changes.split("\n")) {
      if (!change.match(/^\+\s/)) {
        continue;
      }

      const match = change.match(/"(.*?)"/g);

      bumps.set(match[0].replace(/"/g, ""), match[1].replace(/"/g, ""));
    }
  }

