steps.run:
{
  echo "## release / publish"
  echo ""
  echo "No version changes detected — nothing to publish."
} >> "$GITHUB_STEP_SUMMARY"

dotnet tool install --global NuGetKeyVaultSignTool
if ($LASTEXITCODE -ne 0) { throw 'Failed to install NuGetKeyVaultSignTool' }
$toolsDir = Join-Path $env:USERPROFILE '.dotnet\tools'
if ($env:PATH -notlike "*$toolsDir*") { $env:PATH = "$toolsDir;$env:PATH" }

# Short-lived Key Vault data-plane token from the OIDC login context.
$token = az account get-access-token --resource https://vault.azure.net --query accessToken -o tsv
if (-not $token) { throw 'Failed to obtain Key Vault access token' }
Write-Output "::add-mask::$token"

$pkgs = Get-ChildItem -Path artifacts/nuget -File | Where-Object { $_.Extension -eq '.nupkg' }
if ($pkgs.Count -eq 0) { throw 'No .nupkg found to sign' }
foreach ($pkg in $pkgs) {
  Write-Host "Signing $($pkg.Name)"
  NuGetKeyVaultSignTool sign $pkg.FullName `
    --file-digest sha256 `
    --timestamp-rfc3161 http://timestamp.digicert.com `
    --timestamp-digest sha256 `
    --azure-key-vault-url $env:AZURE_KEY_VAULT_URL `
    --azure-key-vault-certificate $env:CODE_SIGNING_CERT_NAME `
    --azure-key-vault-accesstoken $token
  if ($LASTEXITCODE -ne 0) { throw "Signing failed for $($pkg.Name)" }
}

{
  echo "## release / publish — NuGet"
  echo ""
  echo "$DOTNET_PACKAGES" | jq -r '.[] | "- `\(.name)@\(.version)`"'
} >> "$GITHUB_STEP_SUMMARY"

{
  echo ""
  echo "## Canary publish summary — NuGet"
  echo ""
  echo "$DOTNET_PACKAGES" | jq -r '.[] | "```\ndotnet add package \(.name) --version \(.version)\n```"'
} >> "$GITHUB_STEP_SUMMARY"

