function Latest-Semver($repo) {
  $tag = gh api "repos/$repo/releases/latest" --jq '.tag_name' 2>$null
  if ($LASTEXITCODE -ne 0) { return $null }
  if ($tag -match '(\d+\.\d+\.\d+)') { return $Matches[1] }
  return $null
}

# The highest X.Y.Z among $repo's non-draft, non-prerelease release tags,
# or $null if the API call fails. For repos whose `releases/latest` points
# at a rolling non-semver tag — AppImage/appimagetool marks its nightly
# `continuous` release latest — where Latest-Semver finds no digits and
# returns $null, which reads here as a failed query.
function Latest-Semver-Listed($repo) {
  $tags = gh api "repos/$repo/releases" --paginate `
    --jq '.[] | select(.draft == false and .prerelease == false) | .tag_name' 2>$null
  if ($LASTEXITCODE -ne 0) { return $null }
  $versions = @()
  foreach ($tag in $tags) {
    if ($tag -match '(\d+\.\d+\.\d+)') { $versions += [version]$Matches[1] }
  }
  if ($versions.Count -eq 0) { return $null }
  return ($versions | Sort-Object -Descending | Select-Object -First 1).ToString()
}

# The latest stable version of a crates.io crate (the source `cargo
# install <crate> --version X` resolves against — more authoritative
# than GitHub releases, which a crate may not publish), or $null on
# failure. crates.io rejects requests without a User-Agent.
function Latest-CratesIo($crate) {
  try {
    $resp = Invoke-RestMethod -Uri "https://crates.io/api/v1/crates/$crate" `
      -Headers @{ 'User-Agent' = 'bdinfo-rs-version-freshness (github actions)' } -ErrorAction Stop
    return $resp.crate.max_stable_version
  }
  catch { return $null }
}

# The latest published version of an npm package (registry metadata), or
# $null on failure.
function Latest-Npm($pkg) {
  try {
    $resp = Invoke-RestMethod -Uri "https://registry.npmjs.org/$pkg/latest" `
      -Headers @{ 'User-Agent' = 'bdinfo-rs-version-freshness (github actions)' } -ErrorAction Stop
    return $resp.version
  }
  catch { return $null }
}

# The latest published version of a PyPI package (registry metadata), or
# $null on failure.
function Latest-PyPI($pkg) {
  try {
    $resp = Invoke-RestMethod -Uri "https://pypi.org/pypi/$pkg/json" `
      -Headers @{ 'User-Agent' = 'bdinfo-rs-version-freshness (github actions)' } -ErrorAction Stop
    return $resp.info.version
  }
  catch { return $null }
}

