with.script:
const hasRelease = '${{ steps.analyze.outputs.has_release }}' === 'true';
const current = '${{ steps.analyze.outputs.current_version }}';
const next = '${{ steps.analyze.outputs.next_version }}';

const version = hasRelease
  ? `v${current} → **v${next}**`
  : `v${current}（変更なし）`;

let body = `### リリースバージョンプレビュー\n\n`;
body += `| 項目 | 状態 |\n`;
body += `| --- | --- |\n`;
body += `| バージョン | ${version} |\n`;

const { data: comments } = await github.rest.issues.listComments({
  owner: context.repo.owner,
  repo: context.repo.repo,
  issue_number: context.issue.number,
});
const previews = comments
  .filter(c => c.body.includes('### リリースバージョンプレビュー'))
  .sort((a, b) => new Date(b.created_at) - new Date(a.created_at));
const latest = previews[0];

const params = {
  owner: context.repo.owner,
  repo: context.repo.repo,
  body,
};

if (!latest || latest.body !== body) {
  await github.rest.issues.createComment({ ...params, issue_number: context.issue.number });
}

const owner = "backstage";
const repo = "backstage";
const marker = "<!-- changeset-feedback -->";
const feedback = require('fs').readFileSync('feedback.txt', 'utf8');
const issue_number = Number(process.env.ISSUE_NUMBER);
const body = feedback.trim() ? feedback + marker : undefined

const existingComments = await github.paginate(github.rest.issues.listComments, {
  owner,
  repo,
  issue_number,
});

const existingComment = existingComments.find((c) =>
  c.user.login === "github-actions[bot]" &&
  c.body.includes(marker)
);

if (existingComment) {
  if (body) {
    if (existingComment.body !== body) {
      console.log(`updating existing comment in #${issue_number}`);
      await github.rest.issues.updateComment({
        owner,
        repo,
        comment_id: existingComment.id,
        body,
      });
    } else {
      console.log(`skipped update of identical comment in #${issue_number}`);
    }
  } else {
    console.log(`removing comment from #${issue_number}`);
    await github.rest.issues.deleteComment({
      owner,
      repo,
      comment_id: existingComment.id,
      body,
    });
  }
} else if (body) {
  console.log(`creating comment for #${issue_number}`);
  await github.rest.issues.createComment({
    owner,
    repo,
    issue_number,
    body,
  });
}

