const cloudFrontUrl = '${{ needs.deploy-frontend-infrastructure.outputs.cloudfront-url }}';
const backendApiUrl = '${{ needs.deploy-backend.outputs.api-url }}';

const body = [
  '## Deployment Complete',
  '',
  '| Resource | URL |',
  '|----------|-----|',
  `| **UI** | ${cloudFrontUrl} |`,
  `| **API** | ${backendApiUrl} |`,
  '',
  `> Deployed from commit \`${context.sha.substring(0, 7)}\``,
].join('\n');

// Find existing deployment comment to update instead of creating duplicates
const { data: comments } = await github.rest.issues.listComments({
  owner: context.repo.owner,
  repo: context.repo.repo,
  issue_number: context.issue.number,
});

const marker = '## Deployment Complete';
const existing = comments.find(c => c.body.startsWith(marker));

if (existing) {
  await github.rest.issues.updateComment({
    owner: context.repo.owner,
    repo: context.repo.repo,
    comment_id: existing.id,
    body,
  });
} else {
  await github.rest.issues.createComment({
    owner: context.repo.owner,
    repo: context.repo.repo,
    issue_number: context.issue.number,
    body,
  });
}

