steps.run:
{
  echo "## Released ${{ needs.release-please.outputs.tag_name }}"
  echo
  echo "- npm: https://www.npmjs.com/package/@atuscode/atuscode"
  echo "- GitHub: https://github.com/antonioan23/openclaude-atuscode/releases/tag/${{ needs.release-please.outputs.tag_name }}"
} >> "$GITHUB_STEP_SUMMARY"

invocations.raw:
{
  echo "## Released ${{ needs.release-please.outputs.tag_name }}"
  echo
  echo "- npm: https://www.npmjs.com/package/@atuscode/atuscode"
  echo "- GitHub: https://github.com/antonioan23/openclaude-atuscode/releases/tag/${{ needs.release-please.outputs.tag_name }}"
} >> "$GITHUB_STEP_SUMMARY"

with.build-args:
NEXT_PUBLIC_API_URL=${{ secrets.NEXT_PUBLIC_API_BASE_URL }}
NEXTAUTH_CLIENT_ID=${{ secrets.NEXTAUTH_CLIENT_ID }}
NEXT_PUBLIC_APP_URL=${{ secrets.NEXT_PUBLIC_APP_URL }}
NEXT_PUBLIC_SCOPE=${{ secrets.NEXT_PUBLIC_SCOPE }}
NEXT_PUBLIC_UMAMI_SCRIPT_URL=${{ secrets.NEXT_PUBLIC_UMAMI_SCRIPT_URL }}
NEXT_PUBLIC_UMAMI_WEBSITE_ID=${{ secrets.NEXT_PUBLIC_UMAMI_WEBSITE_ID }}

with.script:
const artifacts = await github.rest.actions.listWorkflowRunArtifacts({
   owner: context.repo.owner,
   repo: context.repo.repo,
   run_id: ${{github.event.workflow_run.id }},
});

const matchArtifact = artifacts.data.artifacts.filter((artifact) => {
  return artifact.name == "dependabot-pr-changeset"
})[0];

if (matchArtifact !== undefined) {
  const download = await github.rest.actions.downloadArtifact({
    owner: context.repo.owner,
    repo: context.repo.repo,
    artifact_id: matchArtifact.id,
    archive_format: 'zip',
  });

  const fs = require('fs');
  fs.writeFileSync('/home/runner/work/dependabot-pr.zip', Buffer.from(download.data));
  return true;
}

return false;

await github.rest.actions.reRunWorkflow({
  owner: context.repo.owner,
  repo: context.repo.repo,
  run_id: ${{ github.event.workflow_run.id }},
});

await github.rest.issues.createComment({
  owner: context.repo.owner,
  repo: context.repo.repo,
  issue_number: ${{ needs.update.outputs.pr-number }},
  body: "> [!WARNING]\n> Branch auto synchronized due to changes in generated files. New workflow run triggered:\n>\n> https://github.com/${{ github.repository }}/actions/runs/${{ github.event.workflow_run.id }}\n>\n> Please check the workflow result before merging.\n>\n>If there are multiple commits, please use the **Squash and merge** option."
});

